//Approach 1: Using stack TC: O(n) SC: O(n)
class Solution {
public:
    int scoreOfParentheses(string s) {
        stack<int> stk;
        stk.push(0);
        for(auto it:s)
        {
            if(it=='(')
                stk.push(0);
            else
            {
                int u=stk.top();
                stk.pop();
                int v=stk.top();
                stk.pop();
                stk.push(v+max(2*u,1));
            }
        }
        return stk.top();
    }
};
