class Solution {
public:
    int scoreOfParentheses(string s) {
        int ans=0;
        int depth=0;
        int n=s.size();
        for(int i=0;i<n;i++)
        {
            if(s[i]=='(')
                depth+=1;
            else
            {
                depth-=1;
                if(s[i-1]=='(')
                    ans+=1<<depth;
            }
        }
        return ans;
    }
};

class Solution(object):
    def scoreOfParentheses(self, s):
        """
        :type s: str
        :rtype: int
        """
        st = [0]
        for c in s:
            if c == "(":
                st.append(0)
            else:
                t = st.pop()
                if t == 0:
                    st[-1] += 1
                else:
                    st[-1] += 2 * t
        return st[-1]
